CREATE OR REPLACE TRIGGER trig_location_pk
BEFORE INSERT ON Location
FOR EACH ROW
BEGIN
  :new.no_location := LocID.NEXTVAL;
END;

CREATE OR REPLACE TRIGGER trig_check_permis
BEFORE INSERT ON Location
FOR EACH ROW
DECLARE
  v_permis Client.permis_conduire%TYPE;
BEGIN
  SELECT permis_conduire INTO v_permis
  FROM Client
  WHERE no_client = :new.no_client;

  IF v_permis IS NULL THEN
    RAISE_APPLICATION_ERROR(-20001, 'Le client n''a pas de permis de conduire valide');
  END IF;
END;

CREATE OR REPLACE PROCEDURE ajouter_vehicule_location(
  p_no_location IN NUMBER,
  p_no_vehicule IN NUMBER
)
IS
BEGIN
  INSERT INTO Vehicule_Location(no_location, no_vehicule)
  VALUES (p_no_location, p_no_vehicule);
END;

CREATE OR REPLACE PROCEDURE afficher_top_clients(p_n IN NUMBER)
IS
  CURSOR c_top IS
    SELECT l.no_client, COUNT(vl.no_vehicule) AS nb_vehic
    FROM Location l
    JOIN Vehicule_Location vl ON l.no_location = vl.no_location
    WHERE EXTRACT(YEAR FROM l.date_debut) = EXTRACT(YEAR FROM SYSDATE)
    GROUP BY l.no_client
    ORDER BY nb_vehic DESC;

  v_rank NUMBER := 0;
BEGIN
  FOR r IN c_top LOOP
    v_rank := v_rank + 1;
    IF v_rank = p_n OR v_rank = p_n + 1 THEN
      DBMS_OUTPUT.PUT_LINE('Rang ' || v_rank || ' : Client ' || r.no_client || ' = ' || r.nb_vehic || ' véhicules');
    END IF;
    EXIT WHEN v_rank > p_n + 1;
  END LOOP;
END;
